<?php
declare(strict_types=1);

require dirname(__DIR__) . '/app/bootstrap.php';

use Aetherfall\Formula\FormulaEngine;
use Aetherfall\Formula\Tokenizer;
use Aetherfall\Repositories\CharacterRepository;
use Aetherfall\Services\CharacterAttributeCalculator;
use Aetherfall\Services\CharacterHpCalculator;
use Aetherfall\Services\CharacterValidator;
use Aetherfall\Services\CombatCalculator;
use Aetherfall\Services\CombatValueParser;
use Aetherfall\Services\CombatProfileValueResolver;
use Aetherfall\Services\CriticalDamageCalculator;
use Aetherfall\Support\Json;

$passed=0;$failed=0;
function test(string $name, callable $fn): void { global $passed,$failed;try{$fn();echo "[OK]   {$name}\n";$passed++;}catch(Throwable $e){echo "[FAIL] {$name}: {$e->getMessage()}\n";$failed++;}}
function eq(mixed $expected,mixed $actual,string $message=''):void{if($expected!==$actual)throw new RuntimeException($message?:'Erwartet '.var_export($expected,true).', erhalten '.var_export($actual,true));}
function truth(bool $value,string $message='Bedingung nicht erfüllt'):void{if(!$value)throw new RuntimeException($message);}
function throws(callable $fn,string $class):void{try{$fn();}catch(Throwable $e){if($e instanceof $class)return;throw new RuntimeException('Falscher Exception-Typ: '.$e::class);}throw new RuntimeException('Erwartete Exception wurde nicht ausgelöst.');}

test('JSON-Typ-Erkennung und Schemas',function(){ $expected=['classes'=>'aetherfall.class_abilities.v1','creatures'=>'aetherfall.creatures.v1','bosses'=>'aetherfall.bosses.v1','spells'=>'aetherfall.spells.v1','weapons'=>'aetherfall.weapons.v1'];foreach($expected as$area=>$schema)foreach(glob(BASE_PATH."/json/{$area}/*.json")?:[]as$f){if(basename($f)==='_manifest.json')continue;eq($schema,Json::decodeFile($f)['schema_version']);}});
test('Klassenimport-Quellen und Ability-Verknüpfungen',function(){ $ids=[];$count=0;foreach(glob(BASE_PATH.'/json/classes/*.json')?:[]as$f){if(basename($f)==='_manifest.json')continue;$d=Json::decodeFile($f);$ids[$d['id']]=true;foreach($d['levels']as$l)foreach($l['abilities']as$a){eq($d['id'],$a['class_id']);truth(!isset($ids['ability:'.$a['id']]),'Doppelte Ability-ID');$ids['ability:'.$a['id']]=true;$count++;}}eq(5200,$count);});
test('Spell-Importstruktur',function(){ $ids=[];$count=0;foreach(glob(BASE_PATH.'/json/spells/*.json')?:[]as$f){if(basename($f)==='_manifest.json')continue;$d=Json::decodeFile($f);foreach($d['grades']as$g)foreach($g['spells']as$s){eq($g['grade'],$s['grade']);truth(!isset($ids[$s['id']]),'Doppelte Spell-ID');$ids[$s['id']]=true;$count++;}}eq(600,$count);});
test('Waffen-Importstruktur und stabile IDs',function(){ $ids=[];$count=0;foreach(glob(BASE_PATH.'/json/weapons/*.json')?:[]as$f){if(basename($f)==='_manifest.json')continue;$d=Json::decodeFile($f);eq('aetherfall.weapons.v1',$d['schema_version']);truth(!empty($d['id'])&&!isset($ids[$d['id']]),'Doppelte Waffen-ID');truth(isset($d['name'],$d['core_dice'],$d['formulas']),"Unvollständiges Waffenprofil {$f}");$ids[$d['id']]=true;$count++;}eq(97,$count);});
test('Creature-Level-Importstruktur',function(){ $count=0;foreach(glob(BASE_PATH.'/json/creatures/*.json')?:[]as$f){if(basename($f)==='_manifest.json')continue;$d=Json::decodeFile($f);eq(9,count($d['levels']));$count+=count($d['levels']);}eq(252,$count);});
test('Boss-Level-Importstruktur',function(){ $count=0;foreach(glob(BASE_PATH.'/json/bosses/*.json')?:[]as$f){if(basename($f)==='_manifest.json')continue;$d=Json::decodeFile($f);eq(9,count($d['levels']));$count+=count($d['levels']);}eq(288,$count);});
test('Idempotente stabile Source-IDs',function(){ $store=[];for($run=0;$run<2;$run++)foreach(['classes','creatures','bosses','spells']as$area)foreach(glob(BASE_PATH."/json/{$area}/*.json")?:[]as$f){if(basename($f)==='_manifest.json')continue;$d=Json::decodeFile($f);$store[$area.':'.$d['id']]=$d;}eq(92,count($store));});
test('Formula Tokenizer',function(){ $t=(new Tokenizer())->tokenize('3W10 + WI-Modifikator');eq('dice',$t[0]['type']);eq('identifier',$t[2]['type']);});
test('Formula Parser, Würfel und Variablen',function(){ $e=new FormulaEngine();$r=$e->evaluate('3W10 + 12 + (3 × Stufe) + WI-Modifikator + WI-Bonus + ((EM-Modifikator + EM-Bonus) / 2)',['variables'=>['Stufe'=>2,'WI-Modifikator'=>6,'WI-Bonus'=>0,'EM-Modifikator'=>5,'EM-Bonus'=>0],'dice'=>['3W10'=>21]]);truth($r['supported'],json_encode($r,JSON_UNESCAPED_UNICODE));eq(47.5,$r['value']);});
test('Rundung',function(){ $e=new FormulaEngine();eq(2.0,$e->evaluate('⌊ 5 / 2 ⌋')['value']);eq(3.0,$e->evaluate('⌈ 5 / 2 ⌉')['value']);});
test('Unbekannte Variable fordert Fallback',function(){ $r=(new FormulaEngine())->evaluate('W20 + Waffenbonus',['dice'=>['W20'=>12]]);truth(!$r['supported']);eq('Waffenbonus',$r['missing'][0]);});
test('Normaler Waffenangriff nutzt die gemeinsame Schadenswürfel-Eingabe',function(){ $e=new FormulaEngine();eq('Waffenschaden',$e->extractMath('Führe einen normalen Waffenangriff aus.'));$r=$e->evaluate('Waffenschaden + ST-Modifikator + ST-Bonus',['variables'=>['Waffenschaden'=>17,'ST-Modifikator'=>7,'ST-Bonus'=>2]]);eq(26.0,$r['value']);});
test('Kritischer Schaden: Checkbox aus und an',function(){ $calculator=new CriticalDamageCalculator();$off=$calculator->calculate(10,20,false);eq(0.0,$off['critical_bonus']);eq(10.0,$off['damage_after_critical']);$on=$calculator->calculate(10,20,true);eq(2.0,$on['critical_bonus']);eq(12.0,$on['damage_after_critical']);});
test('Kritischer Schaden: Prozentwerte 50 und 0',function(){ $calculator=new CriticalDamageCalculator();$fifty=$calculator->calculate(100,50,true);eq(50.0,$fifty['critical_bonus']);eq(150.0,$fifty['damage_after_critical']);$zero=$calculator->calculate(100,0,true);eq(0.0,$zero['critical_bonus']);eq(100.0,$zero['damage_after_critical']);});
test('Kreaturen-Kritwert wird aus Combat Values gelesen',function(){ $parser=new CombatValueParser();eq(20.0,$parser->criticalDamagePercent(['values'=>['kritischer_schaden'=>'+20 %']]));eq(25.5,$parser->criticalDamagePercent('{"values":{"kritischer_schaden":"+25,5 %"}}'));eq(null,$parser->criticalDamagePercent(['values'=>[]]));});
test('Mehrspaltige Bosswerte verwenden automatisch Phase 1',function(){ $combat=['values'=>[],'rows'=>[['Kampfwert'=>'Maximale LP','Phase 1'=>'**1250**','Phase 2 – Kernel Exposed'=>'**30080**'],['Kampfwert'=>'Physische Verteidigung','Phase 1'=>'**14**','Phase 2 – Kernel Exposed'=>'**16**'],['Kampfwert'=>'Magieverteidigung','Phase 1'=>'**16**','Phase 2 – Kernel Exposed'=>'**18**'],['Kampfwert'=>'Kritischer Schaden','Phase 1'=>'**+50 %**','Phase 2 – Kernel Exposed'=>'**+70 %**']]];$resolver=new CombatProfileValueResolver();eq(1250,$resolver->maxHp($combat));eq(14,$resolver->physicalDefense($combat));eq(16,$resolver->magicDefense($combat));eq(50.0,(new CombatValueParser())->criticalDamagePercent($combat));});
test('Max LP fallen bei Bedarf auf das Ergebnis der LP-Formel zurück',function(){ $resolver=new CombatProfileValueResolver();$hp=['formulas'=>[['label'=>'Phase 1','formula'=>'100 + 3 = 103,9 LP'],['label'=>'Phase 2','formula'=>'100 + 9 = 109 LP']]];eq(103,$resolver->maxHp([], $hp));});
test('Krit wirkt einmal auf den vollständigen Formelschaden',function(){ $normal=(new FormulaEngine())->evaluate('20 + 10 + 15 + 7 + 3')['value'];eq(55.0,$normal);$result=(new CombatCalculator())->damage($normal,true,20);eq(11.0,$result['critical_bonus']);eq(66.0,$result['damage_after_critical']);eq(66.0,$result['value']);});
test('Krit liegt vor Resistenz und gilt nicht für Heilung',function(){ $calculator=new CombatCalculator();$damage=$calculator->damage(100,true,20,20);eq(120.0,$damage['damage_after_critical']);eq(96.0,$damage['value']);$healing=$calculator->damage(50,true,20,25,10,0,0,false);eq(0.0,$healing['critical_bonus']);eq(50.0,$healing['damage_after_critical']);eq(50.0,$healing['value']);truth(!$healing['critical_applied']);});
test('HP Schaden und Heilung',function(){ $c=new CombatCalculator();eq(0.0,$c->applyDamage(20,30));eq(100.0,$c->applyHealing(90,100,30));});
test('Charaktervalidierung: exakt 11 Attribute und ganzzahlige Eingaben',function(){ $d=['name'=>'A','player_name'=>'B','class_id'=>'c','level'=>1,'critical_damage_percent'=>50,'attributes'=>array_map(fn($c)=>['code'=>$c,'value'=>1,'bonus'=>0],CharacterValidator::ATTRIBUTE_CODES)];eq([], (new CharacterValidator())->validate($d));$missing=$d;array_pop($missing['attributes']);truth(isset((new CharacterValidator())->validate($missing)['attributes']));$d['attributes'][0]['value']=4.9;truth(isset((new CharacterValidator())->validate($d)['attributes']));$d['attributes'][0]['value']=4;$d['attributes'][0]['bonus']=2.5;truth(isset((new CharacterValidator())->validate($d)['attributes']));});
test('Offizielle Attribut-Modifikatortabelle',function(){ $calculator=new CharacterAttributeCalculator();$cases=[1=>-5,2=>-4,3=>-4,4=>-3,5=>-3,8=>-1,9=>-1,10=>0,11=>0,12=>1,13=>1,14=>2,24=>7,25=>7,26=>8,50=>20,51=>20,52=>21,98=>44,99=>44,100=>45];foreach($cases as$value=>$expected)eq($expected,$calculator->calculateModifier($value),"Wert {$value}");});
test('Ungültige Charakterattribute werden nicht extrapoliert',function(){ $calculator=new CharacterAttributeCalculator();foreach([0,-1,101]as$value)throws(fn()=>$calculator->calculateModifier($value),InvalidArgumentException::class);});
test('Automatische maximale LP und konsequentes Abrunden',function(){ $calculator=new CharacterHpCalculator();eq(315,$calculator->calculateMaxHp(10,7,2,4,1));eq(110,$calculator->calculateMaxHp(1,0,0,0,0));eq(180,$calculator->calculateMaxHp(1,5,2,0,0));eq(114,$calculator->calculateMaxHp(1,0,0.45,0,0));eq(114,$calculator->calculateMaxHp(1,0,0.49,0,0));});
test('Aktuelle LP: neu, nicht heilen und bei Senkung kappen',function(){ $calculator=new CharacterHpCalculator();eq(315,$calculator->resolveCurrentHp(null,315,true));eq(120,$calculator->resolveCurrentHp(120,350,false,120));eq(250,$calculator->resolveCurrentHp(280,250,false,280));});
test('Character CRUD ignoriert Client-Modifier und Max LP (SQLite)',function(){ $p=new PDO('sqlite::memory:');$p->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$p->exec("CREATE TABLE classes(id TEXT PRIMARY KEY,name TEXT);CREATE TABLE class_attribute_adjustments(class_id TEXT,role TEXT,attribute_code TEXT,adjustment INTEGER);CREATE TABLE abilities(id TEXT PRIMARY KEY,class_id TEXT,unlock_level INTEGER,number INTEGER,name TEXT,type TEXT,focus TEXT,action_cost TEXT,trigger_requirement TEXT,costs TEXT,class_resource TEXT,usage_limit TEXT,range_text TEXT,target_text TEXT,area_text TEXT,duration_text TEXT,attack_roll TEXT,saving_throw TEXT,dc TEXT,attribute_reference TEXT,damage_type TEXT,calculation TEXT,effect TEXT,target_effect TEXT,status_effect TEXT,stacking TEXT,end_condition TEXT,scaling TEXT,source_file TEXT,source_hash TEXT,raw_json TEXT);CREATE TABLE spell_elements(id TEXT PRIMARY KEY,name TEXT);CREATE TABLE spells(id TEXT PRIMARY KEY,element_id TEXT,grade INTEGER,number INTEGER,name TEXT,effect_type TEXT,mana_cost_raw TEXT,attack_roll TEXT,calculation TEXT,damage_type TEXT,rule_effect TEXT);CREATE TABLE attribute_definitions(code TEXT PRIMARY KEY,name TEXT,sort_order INTEGER);CREATE TABLE characters(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,player_name TEXT,class_id TEXT,level INTEGER,max_hp INTEGER,current_hp INTEGER,critical_damage_percent REAL,created_at TEXT,updated_at TEXT);CREATE TABLE character_attributes(character_id INTEGER,attribute_code TEXT,value REAL,modifier REAL,bonus REAL);CREATE TABLE character_abilities(character_id INTEGER,ability_id TEXT);CREATE TABLE character_spells(character_id INTEGER,spell_id TEXT);");$p->exec("INSERT INTO classes VALUES('c','Klasse');INSERT INTO class_attribute_adjustments VALUES('c','primary','ST',2),('c','secondary','BW',1);INSERT INTO abilities(id,class_id,unlock_level,number,name)VALUES('a','c',1,1,'Fähigkeit');INSERT INTO spell_elements VALUES('e','Feuer');INSERT INTO spells(id,element_id,grade,number,name)VALUES('s','e',1,1,'Zauber');");$i=0;$st=$p->prepare('INSERT INTO attribute_definitions VALUES(?,?,?)');foreach(CharacterValidator::ATTRIBUTE_CODES as$c)$st->execute([$c,$c,++$i]);$data=['name'=>'Held','player_name'=>'Spieler','class_id'=>'c','level'=>1,'max_hp'=>999999,'critical_damage_percent'=>50,'attributes'=>array_map(fn($c)=>['code'=>$c,'value'=>10,'modifier'=>99,'bonus'=>0],CharacterValidator::ATTRIBUTE_CODES),'ability_ids'=>['a'],'spell_ids'=>['s']];$repo=new CharacterRepository($p);$id=$repo->save($data);$row=$repo->find($id);eq(110,(int)$row['max_hp']);eq(110,(int)$row['current_hp']);eq(0,(int)array_values(array_filter($row['attributes'],fn($a)=>$a['attribute_code']==='ST'))[0]['modifier']);eq(11,count($row['attributes']));eq(1,count($row['abilities']));eq(1,count($row['spells']));$p->exec("UPDATE characters SET current_hp=50 WHERE id={$id}");$data['level']=2;unset($data['current_hp']);$repo->save($data,$id);eq(50,(int)$repo->find($id)['current_hp']);$p->exec("UPDATE characters SET current_hp=280 WHERE id={$id}");$data['level']=1;$repo->save($data,$id);$row=$repo->find($id);eq(110,(int)$row['max_hp']);eq(110,(int)$row['current_hp']);$repo->delete($id);eq(null,$repo->find($id));$p->exec("DELETE FROM class_attribute_adjustments WHERE role='secondary'");try{$repo->save($data);throw new RuntimeException('Fehlende Klassenattribute wurden akzeptiert.');}catch(RuntimeException $e){eq('Für diese Klasse ist kein gültiges Haupt- bzw. Sekundärattribut hinterlegt.',$e->getMessage());}});

test('Multiclass effective level und LP-Stufenanteil',function(){ $p=new PDO('sqlite::memory:');$p->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$p->exec("CREATE TABLE classes(id TEXT PRIMARY KEY,name TEXT);CREATE TABLE characters(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,player_name TEXT,class_id TEXT,level INTEGER,max_hp INTEGER,current_hp INTEGER,critical_damage_percent REAL);INSERT INTO classes VALUES('a','A'),('b','B'),('c','C');INSERT INTO characters(name,player_name,class_id,level,max_hp,current_hp,critical_damage_percent)VALUES('x','p','a',20,1,1,0);");$id=(int)$p->lastInsertId();$service=new Aetherfall\Services\CharacterClassService($p);$service->save($id,['primary'=>['class_id'=>'a','class_level'=>8],'secondary_1'=>['class_id'=>'b','class_level'=>20],'secondary_2'=>['class_id'=>'c','class_level'=>12]]);eq(20,$service->effectiveLevel($id));eq(20,(int)$p->query("SELECT level FROM characters WHERE id={$id}")->fetchColumn());$hp=new CharacterHpCalculator();eq(415,$hp->calculateMaxHp($service->effectiveLevel($id),7,2,4,1));});

echo "\n{$passed} bestanden, {$failed} fehlgeschlagen.\n";exit($failed?1:0);

